"""Only replaces dashboard demo JS when the local demo API is enabled."""
API_SCRIPT = "\nconst $=id=>document.getElementById(id);\nconst node=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e};\nconst API='/api/demo';\nlet data=[],selected=null,mode='all',busy=false;\nasync function api(path,options={}){\n  const r=await fetch(API+path,{headers:{'Content-Type':'application/json'},...options});\n  if(!r.ok)throw Error('Demo API returned HTTP '+r.status);\n  return r.json();\n}\nconst stamp=s=>s?new Date(s).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):'';\nfunction notice(text){document.querySelector('.note').textContent=text}\nfunction render(){\n  const q=$('search').value.trim().toLowerCase();const list=$('conversations');list.replaceChildren();\n  const found=data.filter(c=>(mode==='all'||c.unread>0)&&(c.name.toLowerCase().includes(q)||c.msg.some(m=>m[1].toLowerCase().includes(q))));\n  $('countline').textContent=found.length+' conversations';\n  for(const c of found){\n    const b=node('button','conversation'+(c.id===selected?' active':''));b.type='button';\n    const av=node('div','avatar',c.name.split(' ').map(x=>x[0]).join(''));\n    const body=node('div','cbody');const top=node('div','crow');\n    top.append(node('span','cname',c.name),node('span','ctime',stamp(c.last_at)));\n    body.append(top,node('div','cmeta','Demo student'));\n    const bottom=node('div','crow');bottom.append(node('div','preview',c.preview));\n    if(c.unread)bottom.append(node('span','bubblecount',String(c.unread)));\n    body.append(bottom);b.append(av,body);\n    b.onclick=async()=>{\n      selected=c.id;\n      document.querySelector('.layout').classList.add('chat-open');\n      try{await api('/conversations/'+encodeURIComponent(c.id)+'/read',{method:'POST'});await refresh()}\n      catch(err){notice(err.message);render()}\n    };\n    list.append(b);\n  }\n  if(!found.length)list.append(node('div','empty','No matching conversations.'));\n  $('students').textContent=data.length;\n  $('unread').textContent=data.reduce((n,c)=>n+c.unread,0);\n  $('sent').textContent=data.reduce((n,c)=>n+c.msg.filter(m=>m[0]==='out').length,0);\n  showChat();\n}\nfunction showChat(){\n  const c=data.find(x=>x.id===selected),area=$('messages');\n  area.replaceChildren(node('div','date','SYNTHETIC CONVERSATION'));\n  if(!c){$('chatname').textContent='No student';$('level').textContent='';$('avatar').textContent='—';return}\n  $('chatname').textContent=c.name;$('level').textContent='Demo student';\n  $('avatar').textContent=c.name.split(' ').map(x=>x[0]).join('');\n  for(const m of c.msg){\n    const wrap=node('div','msg'+(m[0]==='out'?' out':''));\n    wrap.append(node('p','',m[1]),node('small','',m[2]));area.append(wrap);\n  }\n  area.scrollTop=area.scrollHeight;\n}\nasync function refresh(){\n  const payload=await api('/conversations');\n  const conversations=payload.conversations;\n  const histories=await Promise.all(conversations.map(c=>api('/conversations/'+encodeURIComponent(c.id)+'/messages')));\n  data=conversations.map((c,i)=>({...c,msg:histories[i].messages.map(m=>[\n    m.direction==='outgoing'?'out':'in',m.text,stamp(m.created_at)\n  ])}));\n  if(!data.some(c=>c.id===selected))selected=data[0]?.id??null;\n  render();notice('Connected to the demo backend · Changes last until the server restarts · No WhatsApp messages sent.');\n}\n$('search').oninput=render;\ndocument.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{\n  mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('on',x===b));render();\n});\n$('form').onsubmit=async e=>{\n  e.preventDefault();if(busy||!selected)return;\n  const input=$('reply'),text=input.value.trim();if(!text)return;\n  busy=true;\n  try{\n    await api('/conversations/'+encodeURIComponent(selected)+'/reply',{\n      method:'POST',body:JSON.stringify({text})\n    });\n    input.value='';await refresh();\n  }catch(err){notice('Reply not saved: '+err.message)}finally{busy=false}\n};\n$('reset').onclick=()=>refresh().catch(err=>notice('Refresh failed: '+err.message));\nconst back=$('back-to-inbox');if(back)back.onclick=()=>document.querySelector('.layout').classList.remove('chat-open');\nrefresh().catch(err=>notice('Demo backend unavailable: '+err.message));\n"
def connect_demo_dashboard(template: str) -> str:
    start = template.index("<script>")
    end = template.index("</script>", start) + len("</script>")
    assert template.count("<script>") == 1
    result = template[:start] + "<script>" + API_SCRIPT + "</script>" + template[end:]
    return result.replace(">Reset demo</button>", ">Refresh</button>")
